        FAILED=$((FAILED + 1))
        FAILED_TESTS+=("Test $test_num: $test_name [$rule_id] - Pattern '$json_pattern' not found")
        return 1
    fi
}

# Multipart upload helper (curl -F) — captures $LAST_STATUS + $LAST_BODY
# Usage: multipart_upload "POST" "$URL" "-F 'files=@/path;filename=x' -F 'file_type=Image'"
multipart_upload() {
    local http_method=$1
    local url=$2
    local form_args=$3
    local response

    response=$(eval curl -s -w '"\n%{http_code}"' -X "$http_method" "'$url'" \
        -H "'$TENANT_HEADER'" $form_args)

    LAST_STATUS=$(echo "$response" | tail -1)
    LAST_BODY=$(echo "$response" | sed '$d')
}

